import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const _=JSON.parse('{"title":"4.央国企行测攻略（上）——行测概述","description":"","frontmatter":{},"headers":[],"relativePath":"docs/笔试指南/4.央国企行测攻略（上）——行测概述.md","filePath":"docs/笔试指南/4.央国企行测攻略（上）——行测概述.md","lastUpdated":1788883925000}'),p={name:"docs/笔试指南/4.央国企行测攻略（上）——行测概述.md"};function h(i,a,l,n,s,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="_4-央国企行测攻略-上-——行测概述" tabindex="-1">4.央国企行测攻略（上）——行测概述 <a class="header-anchor" href="#_4-央国企行测攻略-上-——行测概述" aria-label="Permalink to &quot;4.央国企行测攻略（上）——行测概述&quot;">​</a></h1><p><strong>央国企行测攻略（上）——行测概述</strong></p><h1 id="为啥央国企笔试要考行测" tabindex="-1">为啥央国企笔试要考行测？ <a class="header-anchor" href="#为啥央国企笔试要考行测" aria-label="Permalink to &quot;为啥央国企笔试要考行测？&quot;">​</a></h1><p>不知道大家有没有这个疑惑，为啥央企国企跟公务员一样需要考行测呢？这些东西在以后工作中又没有什么作用，到底能测出啥？</p><p>虽然行测在你进央国企之后没啥实际用处，但是培养的一些综合能力还是能够给你带来一些加成的，让你工作起来游刃有余。</p><p>由于央国企并不是所有的都会考试行测，并且行测的占比也不会太大，所以这里用隔壁的公务员考试来举例。</p><h2 id="快速阅读能力" tabindex="-1">快速阅读能力 <a class="header-anchor" href="#快速阅读能力" aria-label="Permalink to &quot;快速阅读能力&quot;">​</a></h2><p>对于非技术岗位来说，央国企工作中最常干的事情就是看各种报表、说明书，这些报表可以是集团的营收情况，也可以是某个项目的开展情况。</p><p>在实际的工作中面对这样一大堆看起来像是要说些什么，但是又不知道说了些什么的文件，没有快速阅读的能力，你可能看都看不完，更别说处理他们了。</p><p>因此，对于公务考试来说，130分钟，135道题，<strong>平均不到一分钟一道题</strong>，首先检测的就是你的快速阅读能力，对题目，以及题目所要表达的含义，在几秒钟之内就能有所了解。</p><h2 id="快速决策能力" tabindex="-1">快速决策能力 <a class="header-anchor" href="#快速决策能力" aria-label="Permalink to &quot;快速决策能力&quot;">​</a></h2><p>整整135道题，时间只有130分钟，平均一道题不到一分钟，其中还有很多并不是很少计算的数学题，需要大量草稿计算才能做出来。</p><p>想要全部仔细思考然后最终得出正确答案几乎是不可能的，因此考试行测的每个孩子都要学会一件事——舍得。</p><p>你必须抛弃掉一部分得分概率并不高的题，花时间去解决那些得分概率更大的题才是你取的高分的关键，这就意味着你在短时间内需要进行大量抉择。</p><p>在以后的工作当中，你将面临众多需要迅速作出选择的情况，这可能涉及个人层面的判断，团队内部的共识形成，或是委员会中的集体决策。</p><p>无论是给予赞成、反对还是保留意见，每种情形都要求你能在紧迫的时间压力下迅速明确立场。</p><p>此外，工作上的的突发事件层出不穷，这就需要你具备敏捷的决策力。犹豫不决往往会导致错失良机，甚至可能引发严重后果。</p><h2 id="对数据的敏感性" tabindex="-1">对数据的敏感性 <a class="header-anchor" href="#对数据的敏感性" aria-label="Permalink to &quot;对数据的敏感性&quot;">​</a></h2><p>行测题目当中的资料分析和数量关系虽然考察的侧重不同，但都为了检测一个人对数据的敏感性。</p><p>资料分析要求你在大量的数据、报表中找到关键信息，得出关键结论，和实际工作中要求看政府工作报告、企业营收报告等工作场景非常贴合。</p><p>而数量关系其实是故意刁难你们的，因为很多题大家如果有时间去慢慢计算都是能够得出正确答案的。</p><p>但是，考试给出的时间确是平均下来1分钟一道题，另外还有图形推理这些不难但是费时间的题需要解决。</p><p>所以，数量关系根本就不是让你慢慢去计算的题，而是让你根据题干中的要求和数据去——蒙一个答案。</p><p>但并不是瞎蒙。蒙是有根据的蒙，是有把握的蒙，<strong>是在30秒内根据少量演算的快速推理前提下的蒙</strong>。</p><p>其实这两种题型最终训练的都是对数据的敏感性，能够在工作中处理大量的数据。</p><h2 id="掌握常识性问题" tabindex="-1">掌握常识性问题 <a class="header-anchor" href="#掌握常识性问题" aria-label="Permalink to &quot;掌握常识性问题&quot;">​</a></h2><p>作为一名央企员工，没有常识是一件很可怕的事情，央企的发展一般都和国家政策有着紧密的联系。</p><p>如果你是一个缺乏基本常识和对国家的政策和经济形势漠不关心的人，那么基础常识就是为了把你筛掉的。</p><p>一般正常读过大学，受过九年义务教育的毕业生们，不用太多余担心这个问题，重点是国家最新的方针政策需要关注一下。</p><h1 id="央国企行测-vs-公务员行测有啥不同" tabindex="-1">央国企行测 VS 公务员行测有啥不同？ <a class="header-anchor" href="#央国企行测-vs-公务员行测有啥不同" aria-label="Permalink to &quot;央国企行测 VS 公务员行测有啥不同？&quot;">​</a></h1><h2 id="央国企行测-vs-公务员行测区别" tabindex="-1">央国企行测 VS 公务员行测区别？ <a class="header-anchor" href="#央国企行测-vs-公务员行测区别" aria-label="Permalink to &quot;央国企行测 VS 公务员行测区别？&quot;">​</a></h2><p>经常考公的朋友们应该都知道，行测的考试内容就那五种，言语理解、判断推理、资料分析、数量分析、基本常识。</p><p>单单就考试内容而言，央国企行测和公务员行测没啥太大区别，区别在于央国企笔试中行测的含量。</p><p>不同的央国企行测的含量不同，例如中国海油的行测含量高达50%，而国家电网行测含量不到20%（剩下的80%都是专业知识）。</p><p>所以，准备去国企的小伙伴儿，最好对自己想去哪类国企有个较为清晰的规划，不要闷头刷行测，这是一种投入产出比很低的行为。</p><p>相反，我甚至不建议大家很早就准备行测，可以采用UP主后面会告诉大家的一种快速突击行测的方法，1个月就可以搞定行测。</p><h2 id="央国企行测所占比例" tabindex="-1">央国企行测所占比例 <a class="header-anchor" href="#央国企行测所占比例" aria-label="Permalink to &quot;央国企行测所占比例&quot;">​</a></h2><p>见《央企手册》中文章“<strong>【笔试指南】3.央国企笔试内容&amp;所占比例</strong>”中相关内容。</p><h1 id="行测考试内容" tabindex="-1">行测考试内容 <a class="header-anchor" href="#行测考试内容" aria-label="Permalink to &quot;行测考试内容&quot;">​</a></h1><h3 id="言语理解" tabindex="-1">言语理解 <a class="header-anchor" href="#言语理解" aria-label="Permalink to &quot;言语理解&quot;">​</a></h3><p>逻辑填空、 阅读理解、 语句表达、篇章阅读、中心理解是常考题型。寻找文段的中心句、关键词、词语之间的规律是解决这类题目的思路。</p><h3 id="判断推理" tabindex="-1">判断推理 <a class="header-anchor" href="#判断推理" aria-label="Permalink to &quot;判断推理&quot;">​</a></h3><p>主要包含图形推理、定义判断、类比推理、逻辑判断四大题型，考察大家对客观事物的分析推理能力，这种题目有非常多秒题技巧，掌握好了可以快速秒题，短时间内答完题，拿到高分。</p><h3 id="资料分析" tabindex="-1">资料分析 <a class="header-anchor" href="#资料分析" aria-label="Permalink to &quot;资料分析&quot;">​</a></h3><p>资料分析主要考察文字、图形、表格等资料的综合理解与分析加工的能力，这部分考察数据、统计、图表分析内容比较多。</p><p>考点主要包括，增长量、增长率、基期值、现期倍数、基期倍数、现期比重、比重变化、现期平均数、基期平均数、隔年增长率、年均增长率、年均增长量等。</p><h3 id="数量分析" tabindex="-1">数量分析 <a class="header-anchor" href="#数量分析" aria-label="Permalink to &quot;数量分析&quot;">​</a></h3><p>数量关系主要考察量化关系和解决数量关系的能力，主要涉及数据关系的分析、推理、判断、运算等。方程、排列组合与概率、几何、基础计算是公考中高频考题。这类题型想要拿到高分一定要掌握答题技巧和方法。</p><p>考点主要包括，等差数列、比例计算、二元一次方程、利润问题、和定最值、最不利原则解题、牛吃草问题、相遇追及、多次相遇（直线同时异地相向）、流水行船、排列组合问题、多次独立重复试验、隔板模型作。前面分享的资料包里面关于排除法、速算法、十字交叉法等常考公示都做了详细的解析。</p><h3 id="基本常识" tabindex="-1">基本常识 <a class="header-anchor" href="#基本常识" aria-label="Permalink to &quot;基本常识&quot;">​</a></h3><p>这个版块其实没固定的题型，主要考察大家对国情社情的了解程度，知识覆盖政治、经济、法律、历史、文化、地理、环境、自然、科技等方面。</p>',51)])])}const u=e(p,[["render",h]]);export{_ as __pageData,u as default};
